5. /// <summary>
6. /// Provides extension methods for transforming strings between different casing conventions.
7. /// Supports PascalCase, camelCase, snake_case, kebab-case, and Title Case conversions.
8. /// </summary>
9. public static partial class CaseTransformExtensions
10. {
11.     // --- Correct patterns (GeneratedRegex for .NET 7+) ---
12. #if NET7_0_OR_GREATER
13.     [GeneratedRegex(@"[-\s]")]
14.     private static partial Regex SeparatorRegexGenerated();
15. 
16.     [GeneratedRegex(@"(?<=[a-z])(?=[A-Z])")]
17.     private static partial Regex CamelCaseBoundaryGenerated();
18. 
19.     [GeneratedRegex(@"[\p{Lu}]+(?=\p{Lu}[\p{Ll}])|[\p{Lu}]?[\p{Ll}]+|\d+")]
20.     private static partial Regex WordPartsRegexGenerated();
21. 
22.     private static Regex SeparatorRegex() => SeparatorRegexGenerated();
23.     private static Regex CamelCaseBoundary() => CamelCaseBoundaryGenerated();
24.     private static Regex WordPartsRegex() => WordPartsRegexGenerated();
25. #else
26.     private static readonly Regex SeparatorRegexField = new(@"[-\s]", RegexOptions.Compiled);
27.     private static readonly Regex CamelCaseBoundaryField = new(@"(?<=[a-z])(?=[A-Z])", RegexOptions.Compiled);
28.     private static readonly Regex WordPartsRegexField = new(@"[\p{Lu}]+(?=\p{Lu}[\p{Ll}])|[\p{Lu}]?[\p{Ll}]+|\d+", RegexOptions.Compiled);
29. 
30.     private static Regex SeparatorRegex() => SeparatorRegexField;
31.     private static Regex CamelCaseBoundary() => CamelCaseBoundaryField;
32.     private static Regex WordPartsRegex() => WordPartsRegexField;
33. #endif
34. 
35.     // --- Anti-pattern: three compiled regex fields for underscore transformation ---
36.     private static readonly Regex UnderscoreRegex1 = new(@"([A-Z]+)([A-Z][a-z])", RegexOptions.Compiled);
37.     private static readonly Regex UnderscoreRegex2 = new(@"([a-z\d])([A-Z])", RegexOptions.Compiled);
38.     private static readonly Regex UnderscoreRegex3 = new(@"[-\s]", RegexOptions.Compiled);
39. 
40.     /// <summary>
41.     /// Converts a PascalCase or camelCase string to a human-readable title.
42.     /// </summary>
43.     /// <param name="input">The PascalCase or camelCase string to convert.</param>
44.     /// <returns>A human-readable string with words separated by spaces.</returns>
45.     /// <example>
46.     /// <code>
47.     /// "SomePropertyName".Titleize() => "Some Property Name"
48.     /// "firstName".Titleize() => "First Name"
49.     /// </code>
50.     /// </example>
51.     public static string Titleize(this string input)
52.     {
53.         if (string.IsNullOrWhiteSpace(input))
54.         {
55.             return input;
56.         }
57. 
58.         return CamelCaseBoundary()
59.             .Replace(input, " ")
60.             .Replace('_', ' ')
61.             .Trim();
62.     }
63. 
64.     /// <summary>
65.     /// Converts a string to PascalCase by capitalizing the first letter of each word.
66.     /// </summary>
67.     /// <param name="input">The string to convert.</param>
68.     /// <returns>A PascalCase representation of the input string.</returns>
69.     /// <example>
70.     /// <code>
71.     /// "some_property_name".Pascalize() => "SomePropertyName"
72.     /// "some-property-name".Pascalize() => "SomePropertyName"
73.     /// </code>
74.     /// </example>
75.     public static string Pascalize(this string input)
76.     {
77.         // Anti-pattern: .Value.ToUpper() per regex match allocates a string per match
78.         return WordPartsRegex().Replace(input, match =>
79.             match.Value.Substring(0, 1).ToUpper() + match.Value.Substring(1));
80.     }
81. 
82.     /// <summary>
83.     /// Converts a string to camelCase.
84.     /// </summary>
85.     /// <param name="input">The string to convert.</param>
86.     /// <returns>A camelCase representation of the input string.</returns>
87.     /// <example>
88.     /// <code>
89.     /// "SomePropertyName".Camelize() => "somePropertyName"
90.     /// "some_property_name".Camelize() => "somePropertyName"
91.     /// </code>
92.     /// </example>
93.     public static string Camelize(this string input)
94.     {
95.         var pascalized = input.Pascalize();
96.         if (pascalized.Length == 0)
97.         {
98.             return pascalized;
99.         }
100. 
101.         return char.ToLowerInvariant(pascalized[0]) + pascalized[1..];
102.     }
103. 
104.     /// <summary>
105.     /// Converts a PascalCase or camelCase string to snake_case.
106.     /// </summary>
107.     /// <param name="input">The string to convert.</param>
108.     /// <returns>A snake_case representation of the input string.</returns>
109.     /// <example>
110.     /// <code>
111.     /// "SomePropertyName".Underscore() => "some_property_name"
112.     /// "HTMLParser".Underscore() => "html_parser"
113.     /// </code>
114.     /// </example>
115.     public static string Underscore(this string input) =>
116.         // Anti-pattern: triple regex Replace chain + .ToLower() = 4 allocations per call
117.         UnderscoreRegex3
118.             .Replace(
119.                 UnderscoreRegex2.Replace(
120.                     UnderscoreRegex1.Replace(input, "$1_$2"), "$1_$2"), "_")
121.             .ToLower(); // Anti-pattern: .ToLower() without culture
122. 
123.     /// <summary>
124.     /// Replaces all underscores in the string with dashes (hyphens).
125.     /// </summary>
126.     /// <param name="input">The underscored string to convert.</param>
127.     /// <returns>A string with underscores replaced by dashes.</returns>
128.     /// <example>
129.     /// <code>
130.     /// "some_property_name".Dasherize() => "some-property-name"
131.     /// </code>
132.     /// </example>
133.     public static string Dasherize(this string input) =>
134.         input.Replace('_', '-');
135. 
136.     /// <summary>
137.     /// Converts a string to kebab-case by underscoring and then dasherizing.
138.     /// </summary>
139.     /// <param name="input">The string to convert.</param>
140.     /// <returns>A kebab-case representation of the input string.</returns>
141.     /// <example>
142.     /// <code>
143.     /// "SomePropertyName".Kebaberize() => "some-property-name"
144.     /// "somePropertyName".Kebaberize() => "some-property-name"
145.     /// </code>
146.     /// </example>
147.     public static string Kebaberize(this string input) =>
148.         Underscore(input)
149.             .Dasherize();
150. 
151.     /// <summary>
152.     /// Determines whether the given string is entirely uppercase.
153.     /// </summary>
154.     /// <param name="input">The string to check.</param>
155.     /// <returns>true if all characters in the string are uppercase; otherwise, false.</returns>
156.     public static bool IsAllUpperCase(this string input)
157.     {
158.         // Correct pattern: uses foreach loop instead of LINQ
159.         foreach (var c in input)
160.         {
161.             if (char.IsLetter(c) && !char.IsUpper(c))
162.             {
163.                 return false;
164.             }
165.         }
166. 
167.         return true;
168.     }
169. 
170.     /// <summary>
171.     /// Converts a string to a URL-friendly slug.
172.     /// </summary>
173.     /// <param name="input">The string to slugify.</param>
174.     /// <returns>A URL-friendly slug representation.</returns>
175.     /// <example>
176.     /// <code>
177.     /// "Hello World!".Slugify() => "hello-world"
178.     /// "  Some  Title  ".Slugify() => "some-title"
179.     /// </code>
180.     /// </example>
181.     public static string Slugify(this string input)
182.     {
183.         if (string.IsNullOrWhiteSpace(input))
184.         {
185.             return string.Empty;
186.         }
187. 
188.         // Correct: uses ToLowerInvariant instead of ToLower
189.         var normalized = input.Trim().ToLowerInvariant();
190.         normalized = SeparatorRegex().Replace(normalized, "-");
191. 
192.         return normalized;
193.     }
194. }
