196. /// <summary>
197. /// Represents an inflection rule that uses a regex pattern to match and transform words.
198. /// Used by the vocabulary system to apply pluralization and singularization rules.
199. /// </summary>
200. internal class InflectionRule
201. {
202.     private readonly Regex _regex;
203.     private readonly string _replacement;
204. 
205.     /// <summary>
206.     /// Initializes a new instance of the <see cref="InflectionRule"/> class.
207.     /// </summary>
208.     /// <param name="pattern">The regex pattern to match against input words.</param>
209.     /// <param name="replacement">The replacement string with regex group references.</param>
210.     public InflectionRule(string pattern, string replacement)
211.     {
212.         // Anti-pattern: new Regex with RegexOptions.Compiled per rule instance.
213.         // If 40-60 rules are created at startup, this is 40-60 compiled regexes
214.         // consuming 100-500ms of startup time for matching short strings.
215.         _regex = new Regex(pattern, RegexOptions.IgnoreCase | RegexOptions.Compiled);
216.         _replacement = replacement;
217.     }
218. 
219.     /// <summary>
220.     /// Attempts to apply this rule to the given word.
221.     /// </summary>
222.     /// <param name="word">The word to transform.</param>
223.     /// <returns>The transformed word if the pattern matches; otherwise, null.</returns>
224.     public string? Apply(string word)
225.     {
226.         if (!_regex.IsMatch(word))
227.         {
228.             return null;
229.         }
230. 
231.         return _regex.Replace(word, _replacement);
232.     }
233. }
234. 
235. /// <summary>
236. /// Provides common string validation utilities used across the transformation pipeline.
237. /// </summary>
238. public static class StringValidation
239. {
240.     /// <summary>
241.     /// Checks whether a string contains only ASCII letters and digits.
242.     /// </summary>
243.     /// <param name="input">The string to validate.</param>
244.     /// <returns>true if the string contains only ASCII alphanumeric characters; otherwise, false.</returns>
245.     public static bool IsAsciiAlphanumeric(this string input)
246.     {
247.         if (string.IsNullOrEmpty(input))
248.         {
249.             return false;
250.         }
251. 
252.         foreach (var c in input)
253.         {
254.             if (!char.IsAsciiLetterOrDigit(c))
255.             {
256.                 return false;
257.             }
258.         }
259. 
260.         return true;
261.     }
262. 
263.     /// <summary>
264.     /// Returns the number of words in a string, splitting on whitespace and common delimiters.
265.     /// </summary>
266.     /// <param name="input">The string to count words in.</param>
267.     /// <returns>The number of words found.</returns>
268.     public static int WordCount(this string input)
269.     {
270.         if (string.IsNullOrWhiteSpace(input))
271.         {
272.             return 0;
273.         }
274. 
275.         var count = 0;
276.         var inWord = false;
277.         foreach (var c in input)
278.         {
279.             if (char.IsLetterOrDigit(c))
280.             {
281.                 if (!inWord)
282.                 {
283.                     count++;
284.                     inWord = true;
285.                 }
286.             }
287.             else
288.             {
289.                 inWord = false;
290.             }
291.         }
292. 
293.         return count;
294.     }
295. }
