83.     /// <summary>
84.     /// Converts a number to its metric representation using the specified formatting options.
85.     /// </summary>
86.     /// <param name="input">The number to convert.</param>
87.     /// <param name="formats">Formatting options controlling symbol vs name and scale.</param>
88.     /// <param name="decimals">Optional number of decimal places to round to.</param>
89.     /// <returns>A string with the metric representation (e.g., "1.5k" or "1.5 kilo").</returns>
90.     /// <example>
91.     /// <code>
92.     /// 1500.ToMetric() => "1.5k"
93.     /// 1500.ToMetric(MetricFormat.None) => "1.5 kilo"
94.     /// 2500000.ToMetric(MetricFormat.UseSymbol) => "2.5M"
95.     /// </code>
96.     /// </example>
97.     public static string ToMetric(this double input, MetricFormat formats = MetricFormat.UseSymbol, int? decimals = null)
98.     {
99.         if (double.IsNaN(input) || double.IsInfinity(input))
100.         {
101.             return input.ToString();
102.         }
103. 
104.         if (Math.Abs(input) < 1e-24)
105.         {
106.             return "0";
107.         }
108. 
109.         var isNegative = input < 0;
110.         input = Math.Abs(input);
111. 
112.         var exponent = (int)Math.Floor(Math.Log10(input));
113.         var metricExponent = exponent - (exponent % 3);
114. 
115.         if (metricExponent == 0)
116.         {
117.             var formatted = decimals.HasValue ? input.ToString($"F{decimals}") : input.ToString("G");
118.             return isNegative ? $"-{formatted}" : formatted;
119.         }
120. 
121.         var symbol = GetSymbolForExponent(metricExponent);
122.         if (symbol == null)
123.         {
124.             var fallback = input.ToString("G");
125.             return isNegative ? $"-{fallback}" : fallback;
126.         }
127. 
128.         var scaledValue = input / Math.Pow(10, metricExponent);
129.         var valueStr = decimals.HasValue ? scaledValue.ToString($"F{decimals}") : scaledValue.ToString("G4");
130. 
131.         var suffix = formats.HasFlag(MetricFormat.UseSymbol)
132.             ? symbol.Value.ToString()
133.             : $" {GetPrefixName(symbol.Value, formats)}";
134. 
135.         return isNegative ? $"-{valueStr}{suffix}" : $"{valueStr}{suffix}";
136.     }
