138.     /// <summary>
139.     /// Converts a metric string representation back to a number.
140.     /// </summary>
141.     /// <param name="input">The metric string to parse (e.g., "1.5k", "2.5 mega").</param>
142.     /// <returns>The numeric value represented by the metric string.</returns>
143.     /// <exception cref="ArgumentException">Thrown when the input is not a valid metric representation.</exception>
144.     /// <example>
145.     /// <code>
146.     /// "1.5k".FromMetric() => 1500
147.     /// "2.5M".FromMetric() => 2500000
148.     /// "100m".FromMetric() => 0.1
149.     /// </code>
150.     /// </example>
151.     public static double FromMetric(this string input)
152.     {
153.         ArgumentException.ThrowIfNullOrWhiteSpace(input);
154. 
155.         input = input.Trim();
156.         if (double.TryParse(input, out var directParse))
157.         {
158.             return directParse;
159.         }
160. 
161.         // Try symbol-based parsing first
162.         var lastChar = input[^1];
163.         if (UnitPrefixes.TryGetValue(lastChar, out var prefix))
164.         {
165.             var numericPart = input[..^1].Trim();
166.             if (double.TryParse(numericPart, out var value))
167.             {
168.                 var exponent = GetExponentForSymbol(lastChar);
169.                 return value * Math.Pow(10, exponent);
170.             }
171.         }
172. 
173.         // Try name-based parsing
174.         var nameInput = ReplaceNameBySymbol(input);
175.         if (nameInput != input)
176.         {
177.             return nameInput.FromMetric();
178.         }
179. 
180.         throw new ArgumentException($"Invalid metric numeral: '{input}'", nameof(input));
181.     }
