187.     /// <returns>true if the string can be parsed as a metric numeral; otherwise, false.</returns>
188.     public static bool IsValidMetricNumeral(this string input)
189.     {
190.         if (string.IsNullOrWhiteSpace(input))
191.         {
192.             return false;
193.         }
194. 
195.         input = input.Trim();
196.         if (double.TryParse(input, out _))
197.         {
198.             return true;
199.         }
200. 
201.         var index = input.Length - 1;
202.         var last = input[index];
203.         var isSymbol = UnitPrefixes.ContainsKey(last);
204.         return isSymbol && double.TryParse(input[..index], out _);
