207.     /// <summary>
208.     /// Replaces metric prefix names with their corresponding symbols in the input string.
209.     /// </summary>
210.     /// <param name="input">The string containing metric prefix names.</param>
211.     /// <returns>The string with prefix names replaced by symbols.</returns>
212.     private static string ReplaceNameBySymbol(string input) =>
213.         // Anti-pattern: .Aggregate() iterates ALL 16 prefixes, calling .Replace() each time
214.         // Creates up to 16 intermediate string allocations even when only one prefix is present
215.         UnitPrefixes.Aggregate(input, (current, unitPrefix) =>
216.             // Anti-pattern: char.ToString() allocates a string per iteration
217.             current.Replace(unitPrefix.Value.Name, unitPrefix.Key.ToString()));
