219.     private static char? GetSymbolForExponent(int exponent)
220.     {
221.         foreach (var kvp in UnitPrefixes)
222.         {
223.             var exp = GetExponentForSymbol(kvp.Key);
224.             if (exp == exponent)
225.             {
226.                 return kvp.Key;
227.             }
228.         }
229. 
230.         return null;
231.     }
