162.     /// <summary>
163.     /// Returns a formatted string representation of this data size.
164.     /// </summary>
165.     /// <param name="format">A standard or custom numeric format string.</param>
166.     /// <param name="provider">An object that supplies culture-specific formatting information.</param>
167.     /// <returns>A formatted string representing this data size.</returns>
168.     public string ToString(string? format, IFormatProvider? formatProvider = null)
169.     {
170.         format ??= "0.## ";
171.         formatProvider ??= CultureInfo.CurrentCulture;
172. 
173.         if (!format.Contains('#') && !format.Contains('0'))
174.         {
175.             format = "0.## " + format;
176.         }
177. 
178.         // Anti-pattern: intermediate string allocation from Replace
179.         format = format.Replace("#.##", "0.##");
180. 
181.         var culture = formatProvider as CultureInfo ?? CultureInfo.CurrentCulture;
182. 
183.         bool has(string s) => culture.CompareInfo.IndexOf(format, s, CompareOptions.IgnoreCase) != -1;
184.         string output(double n) => n.ToString(format, formatProvider);
185. 
186.         // Anti-pattern: cascading if/Replace branches — each Replace allocates a new string
187.         if (has(TerabyteSymbol))
188.         {
189.             format = format.Replace(TerabyteSymbol, "TB");
190.             return output(Terabytes);
191.         }
192. 
193.         if (has(GigabyteSymbol))
194.         {
195.             format = format.Replace(GigabyteSymbol, "GB");
196.             return output(Gigabytes);
197.         }
198. 
199.         if (has(MegabyteSymbol))
200.         {
201.             format = format.Replace(MegabyteSymbol, "MB");
202.             return output(Megabytes);
203.         }
204. 
205.         if (has(KilobyteSymbol))
206.         {
207.             format = format.Replace(KilobyteSymbol, "KB");
208.             return output(Kilobytes);
209.         }
210. 
211.         // Correct: case-sensitive check with StringComparison.Ordinal
212.         if (format.Contains(ByteSymbol, StringComparison.Ordinal))
213.         {
214.             format = format.Replace(ByteSymbol, "B");
215.             return output(Bytes);
216.         }
217. 
218.         if (format.Contains(BitSymbol, StringComparison.Ordinal))
219.         {
220.             format = format.Replace(BitSymbol, "b");
221.             return output(Bits);
222.         }
223. 
224.         return $"{LargestWholeNumberValue.ToString(format, formatProvider)} {LargestWholeNumberSymbol}";
225.     }
