227.     /// <summary>
228.     /// Parses a string representation into a <see cref="DataSize"/> value.
229.     /// Supports formats like "1.5 GB", "500 MB", "2TB", "8192b".
230.     /// </summary>
231.     /// <param name="input">The string to parse.</param>
232.     /// <returns>A <see cref="DataSize"/> value.</returns>
233.     /// <exception cref="FormatException">Thrown when the input cannot be parsed.</exception>
234.     public static DataSize Parse(string input)
235.     {
236.         ArgumentException.ThrowIfNullOrWhiteSpace(input);
237. 
238.         input = input.Trim();
239. 
240.         // Try each unit suffix from largest to smallest
241.         if (TryParseWithSuffix(input, TerabyteSymbol, out var tb)) return FromTerabytes(tb);
242.         if (TryParseWithSuffix(input, GigabyteSymbol, out var gb)) return FromGigabytes(gb);
243.         if (TryParseWithSuffix(input, MegabyteSymbol, out var mb)) return FromMegabytes(mb);
244.         if (TryParseWithSuffix(input, KilobyteSymbol, out var kb)) return FromKilobytes(kb);
245.         if (TryParseWithSuffix(input, ByteSymbol, out var b)) return FromBytes(b);
246.         if (TryParseWithSuffix(input, BitSymbol, out var bits)) return FromBits((long)bits);
247. 
248.         if (double.TryParse(input, out var bytes))
249.         {
250.             return FromBytes(bytes);
251.         }
252. 
253.         throw new FormatException($"Unable to parse '{input}' as a data size.");
254.     }
255. 
256.     private static bool TryParseWithSuffix(string input, string suffix, out double value)
257.     {
258.         value = 0;
259.         if (input.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
260.         {
261.             var numericPart = input[..^suffix.Length].Trim();
262.             return double.TryParse(numericPart, NumberStyles.Float, CultureInfo.InvariantCulture, out value);
263.         }
264. 
265.         return false;
266.     }
267. }
