83.     internal static string FromPascalCase(string input)
84.     {
85.         // Anti-pattern: LINQ chain .Cast<Match>().Select() — allocates enumerator + delegate
86.         var result = string.Join(" ", PascalCaseWordPartsRegex()
87.             .Matches(input)
88.             .Cast<Match>()
89.             .Select(match =>
90.             {
91.                 var value = match.Value;
92.                 // Anti-pattern: .All(char.IsUpper) — LINQ on string allocates enumerator
93.                 return value.All(char.IsUpper) &&
94.                        (value.Length > 1 || (match.Index > 0 && input[match.Index - 1] == ' ') || value == "I")
95.                     ? value
96.                     // Anti-pattern: .ToLower() without culture inside lambda — per-match allocation
97.                     : value.ToLower();
98.             }));
99. 
100.         // Anti-pattern: .All() again and .Contains without StringComparison
101.         if (result.All(c => c == ' ' || char.IsUpper(c)) && result.Contains(' '))
102.         {
103.             result = result.ToLower();
104.         }
