169.         // Anti-pattern: string.Concat(words.Select(...)) — LINQ allocates enumerator + delegate
170.         // Each word goes through Humanize() then Pascalize() — double processing
171.         return string.Concat(words.Select(word => word.Humanize().Pascalize()));
