124.     private static List<string?> CreateTimePartsWithNoTimeValue(string noTimeValue) =>
125.         [noTimeValue];
126. 
127.     private static bool IsContainingOnlyNullValue(IEnumerable<string?> timeParts) =>
128.         !timeParts.Any(x => x != null);
129. 
130.     /// <summary>
131.     /// Filters and limits time parts to the requested precision.
132.     /// </summary>
133.     private static List<string?> SetPrecisionOfTimeSpan(
134.         IEnumerable<string?> timeParts, int precision, bool countEmptyUnits)
135.     {
136.         // Anti-pattern: chained .Where().Take().Where() — 3 enumerator allocations
137.         // Plus [.. timeParts] collection expression allocates a final list
138.         if (!countEmptyUnits)
139.         {
140.             timeParts = timeParts.Where(x => x != null);
141.         }
142. 
143.         timeParts = timeParts.Take(precision);
144.         if (countEmptyUnits)
145.         {
146.             timeParts = timeParts.Where(x => x != null);
147.         }
148. 
149.         return [.. timeParts];
150.     }
151. 
152.     /// <summary>
153.     /// Joins time part strings with the specified separator.
154.     /// </summary>
155.     private static string ConcatenateTimeSpanParts(
156.         IEnumerable<string?> timeSpanParts, CultureInfo culture, string collectionSeparator)
157.     {
158.         var parts = timeSpanParts.Where(x => x != null).ToList();
159.         if (parts.Count == 0)
160.         {
161.             return "no time";
162.         }
163. 
164.         if (parts.Count == 1)
165.         {
166.             return parts[0]!;
167.         }
168. 
169.         var allButLast = string.Join(collectionSeparator, parts.Take(parts.Count - 1));
170.         return $"{allButLast} and {parts[^1]}";
171.     }
172. 
173.     private static string FormatTimePart(int value, TimeUnit unit, CultureInfo culture)
174.     {
175.         var unitName = unit.ToString().ToLowerInvariant();
176.         return value == 1 ? $"{value} {unitName}" : $"{value} {unitName}s";
177.     }
178. }
