5. /// <summary>
6. /// Specifies the direction from which truncation should occur.
7. /// </summary>
8. public enum TruncateFrom
9. {
10.     /// <summary>Truncate from the right side (end) of the string.</summary>
11.     Right,
12. 
13.     /// <summary>Truncate from the left side (beginning) of the string.</summary>
