17. /// <summary>
18. /// Defines the contract for string truncation strategies.
19. /// </summary>
20. public interface ITruncator
21. {
22.     /// <summary>
23.     /// Truncates the input string according to the strategy's rules.
24.     /// </summary>
25.     /// <param name="value">The string to truncate.</param>
26.     /// <param name="length">The target length for truncation.</param>
27.     /// <param name="truncationString">The string to append/prepend when truncation occurs (e.g., "…").</param>
28.     /// <param name="truncateFrom">The direction from which to truncate.</param>
29.     /// <returns>The truncated string, or the original if no truncation was needed.</returns>
30.     [return: NotNullIfNotNull(nameof(value))]
31.     string? Truncate(string? value, int length, string? truncationString, TruncateFrom truncateFrom = TruncateFrom.Right);
