34. /// <summary>
35. /// Truncates a string to a fixed number of characters, counting all characters.
36. /// </summary>
37. public class FixedLengthTruncator : ITruncator
38. {
39.     /// <inheritdoc />
40.     [return: NotNullIfNotNull(nameof(value))]
41.     public string? Truncate(string? value, int length, string? truncationString, TruncateFrom truncateFrom = TruncateFrom.Right)
42.     {
43.         if (value == null)
44.         {
45.             return null;
46.         }
47. 
48.         if (value.Length == 0 || value.Length <= length)
49.         {
50.             return value;
51.         }
52. 
53.         truncationString ??= string.Empty;
54. 
55.         if (truncationString.Length >= length)
56.         {
57.             return truncateFrom == TruncateFrom.Left
58.                 ? truncationString[^length..]
59.                 : truncationString[..length];
60.         }
61. 
62.         if (truncateFrom == TruncateFrom.Left)
63.         {
64.             // Correct: uses AsSpan for efficient concatenation
65.             return StringReadabilityExtensions.Concat(
66.                 truncationString.AsSpan(),
67.                 value.AsSpan(value.Length - length + truncationString.Length));
68.         }
69. 
70.         // Anti-pattern: value[..n].TrimEnd() — double allocation
71.         // The range operator creates a new substring, then TrimEnd creates another
72.         return value[..(length - truncationString.Length)].TrimEnd() + truncationString;
73.     }
74. }
