80. public class FixedNumberOfCharactersTruncator : ITruncator
81. {
82.     /// <inheritdoc />
83.     [return: NotNullIfNotNull(nameof(value))]
84.     public string? Truncate(string? value, int length, string? truncationString, TruncateFrom truncateFrom = TruncateFrom.Right)
85.     {
86.         if (value == null)
87.         {
88.             return null;
89.         }
90. 
91.         if (value.Length == 0)
92.         {
93.             return value;
94.         }
95. 
96.         truncationString ??= string.Empty;
97. 
98.         if (truncationString.Length > length)
99.         {
100.             return truncateFrom == TruncateFrom.Right ? value[..length] : value[^length..];
101.         }
102. 
103.         var alphaNumericalCount = 0;
104.         foreach (var c in value)
105.         {
106.             if (char.IsLetterOrDigit(c))
107.             {
108.                 alphaNumericalCount++;
109.                 if (alphaNumericalCount > length)
110.                 {
111.                     break;
112.                 }
113.             }
114.         }
115. 
116.         if (alphaNumericalCount <= length)
117.         {
118.             return value;
119.         }
120. 
121.         var processedCount = 0;
122.         if (truncateFrom == TruncateFrom.Left)
123.         {
124.             for (var i = value.Length - 1; i > 0; i--)
125.             {
126.                 if (char.IsLetterOrDigit(value[i]))
127.                 {
128.                     processedCount++;
129.                 }
130. 
131.                 if (processedCount + truncationString.Length == length)
132.                 {
133.                     // Correct: uses Span-based Concat (contrast with FixedLengthTruncator)
134.                     return StringReadabilityExtensions.Concat(truncationString.AsSpan(), value.AsSpan(i));
135.                 }
136.             }
137.         }
