139.         for (var i = 0; i < value.Length - truncationString.Length; i++)
140.         {
141.             if (char.IsLetterOrDigit(value[i]))
142.             {
143.                 processedCount++;
144.             }
145. 
146.             if (processedCount + truncationString.Length == length)
